import java.util.HashMap;
import java.util.Map;

public class HashMapInternalsDemo {
    public static void main(String[] args) {
        // Initializing with a custom capacity and default load factor (0.75)
        Map<String, UserSession> sessionCache = new HashMap<>(32);

        sessionCache.put("user_91823", new UserSession("Active"));
        sessionCache.put("user_44120", new UserSession("Idle"));

        // Retrieval triggers internal hash calculation and bucket lookup
        UserSession session = sessionCache.get("user_91823");
        System.out.println("Session Status: " + session.getStatus());
    }

    static class UserSession {
        private final String status;
        public UserSession(String status) { this.status = status; }
        public String getStatus() { return status; }
    }
}
